def _originals(g,inp,valid,*,interpolation=False):
    """Evaluate each complete original physical ring exactly once."""
    sites=inp.outputs['Chain Sites'];i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    ri=g.node('GeometryNodeRepeatInput','Original physical corner rings')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro);ro.repeat_items.clear()
