    count=named('count');first=named('first');a=named('a');end=named('b')
    acc=g.node('GeometryNodeAccumulateField');acc.data_type='INT';acc.domain='POINT';g.bind(count,acc.inputs['Value'])
    good=g.math('COMPARE',first,acc.outputs['Trailing'])*g.math('GREATER_THAN',count,.5)
    good=good*g.math('COMPARE',end,read(links,'a',g.math('MODULO',i+1.,nl)))
    good=good*g.math('COMPARE',a,read(steps,'corner',first))
    for value in (a,end):good=good*g.math('GREATER_THAN',value,-.5)*g.math('LESS_THAN',value,nr-.5)
    good=good*old('valid',a,'BOOLEAN')*old('valid',end,'BOOLEAN')
    basic=basic*c._stat(g,links,good)*g.math('COMPARE',c._stat(g,links,count,'Sum'),nt)
    owner=named('owner');corner=named('corner');span=named('span');mid_a=named('mid_a');mid_b=named('mid_b')
    first=read(links,'first',owner);count=read(links,'count',owner)
    last=g.math('COMPARE',i,first+count-1.);active=1.-last
    good=g.math('GREATER_THAN',owner,-.5)*g.math('LESS_THAN',owner,nl-.5)
    good=good*g.math('GREATER_THAN',i,first-.5)*g.math('LESS_THAN',i,first+count-.5)
    good=good*c.choose(g,active,g.math('GREATER_THAN',span,-.5),g.math('COMPARE',span,-1.))
    for value in (corner,mid_a,mid_b):good=good*g.math('GREATER_THAN',value,-.5)*g.math('LESS_THAN',value,nr-.5)
    next_port=c._read(g,originals,'_lq_next',corner,'INT')
    identity=g.math('COMPARE',next_port,mid_a)*g.math('COMPARE',mid_b,read(steps,'corner',i+1.))
    identity=identity*g.math('COMPARE',old('span_index',mid_a,'INT'),span)*g.math('COMPARE',old('span_index',mid_b,'INT'),span)
    identity=identity*g.math('COMPARE',old('reverse',mid_a,'INT')+old('reverse',mid_b,'INT'),1.)
    for key,sign in (('width',1.),('offset',-1.),('rise',1.),('datum',1.),('half',-1.)):
        identity=identity*g.math('LESS_THAN',g.math('ABSOLUTE',old(key,mid_a)-sign*old(key,mid_b)),1e-6)
    good=good*c.choose(g,active,identity,g.math('COMPARE',next_port,read(links,'b',owner)))
    flag=named('footprint');good=good*(g.math('COMPARE',flag,0.)+active*g.math('COMPARE',flag,1.))
    basic=basic*c._stat(g,steps,good)
    mouths=links;a=named('a')
    for key,kind in (('parameter','FLOAT'),('nominal_parameter','FLOAT'),('length','FLOAT'),('width','FLOAT'),('offset','FLOAT'),
                    ('position','FLOAT_VECTOR'),('tangent','FLOAT_VECTOR'),('endpoint','FLOAT_VECTOR'),('valid','BOOLEAN'),
                    ('weighted','BOOLEAN'),('street_id','INT'),('section_id','INT'),('span_index','INT'),('connector_id','INT'),
                    ('junction_id','INT'),('reverse','INT'),('half','INT'),('rise','FLOAT'),('datum','FLOAT'),('input_index','INT')):
        mouths=c._store(g,mouths,'st_cj_'+key,old(key,a,kind),kind)
    if interpolation:
        for key,kind in (('profile_axis','FLOAT_VECTOR'),('polyline','BOOLEAN')):
            mouths=c._store(g,mouths,'st_cj_'+key,old(key,a,kind),kind)
    mouths=c._store(g,mouths,'st_cj_order',i,'INT')
    basic=basic*c._stat(g,mouths,g.math('LESS_THAN',g.math('ABSOLUTE',c.named(g,'st_cj_datum')-c._read(g,mouths,'st_cj_datum',0)),1e-6))
    # Evaluate source lengths and original contacts once for each chain step.
