def _emit(g,inp,links,steps,originals,corners,approaches,valid,*,interpolation=False):
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);nl=c._count(g,links)
    cell=g.math('MAXIMUM',inp.outputs['Cell Size'],.02)
    ri=g.node('GeometryNodeRepeatInput','Ordered original corners and curved curb chains')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(c.choose(g,valid,c._count(g,steps),0,'INT'),ri.inputs['Iterations']);at=c.V(g,ri.outputs['Iteration'])
    read=lambda key,kind='INT':c._read(g,steps,'st_lq_'+key,at,kind)
    scalar=lambda key:c._read(g,steps,'_lq_'+key,at)
    owner=read('owner');corner=read('corner');active=g.math('GREATER_THAN',read('span'),-.5)
    first=c._read(g,links,'st_lq_first',owner,'INT');is_first=g.math('COMPARE',at,first);is_last=1.-active
    a=c._read(g,links,'st_lq_a',owner,'INT');end=c._read(g,links,'st_lq_b',owner,'INT')
    def old(key,idx,kind='FLOAT'):return c._read(g,originals,'st_cj_'+key,idx,kind)
    h0=b._profile(g,0.,old('half',a,'INT'),old('rise',a))+old('datum',a)
    h1=b._profile(g,1.,old('half',end,'INT'),old('rise',end))+old('datum',end)
    pa=_source(g,inp,approaches,a,interpolation=interpolation);pb=_source(g,inp,approaches,end,interpolation=interpolation);middle=_source(g,inp,approaches,read('mid_a'),interpolation=interpolation)
    edge=b._edge_piece(g,pa.outputs['Geometry'],old('parameter',a),c._read(g,corners,'st_cc_sa',corner),
                       old('offset',a)-.5*old('width',a),h0,cell,0,owner,polyline=interpolation)
    pieces=[b._empty(g,edge,is_first)]
    arc=compound._continuation_piece(g,corners,corner,scalar('arc_length'),cell,owner,
        c.choose(g,is_first,1,5,'INT'),h0,h1,scalar('distance'),scalar('total'))
    pieces.append(b._empty(g,arc,g.math('GREATER_THAN',scalar('arc_length'),1e-8)))
    fraction=(scalar('distance')+scalar('arc_length')+c.named(g,'st_cj_parameter')-scalar('start'))/g.math('MAXIMUM',scalar('total'),1e-12)
    height=h0+(h1-h0)*fraction**3.*(10.+fraction*(-15.+6.*fraction))
    edge=b._edge_piece(g,middle.outputs['Geometry'],scalar('start'),scalar('end'),scalar('offset'),height,cell,4,owner,polyline=interpolation)
    pieces.append(b._empty(g,edge,active*g.math('GREATER_THAN',scalar('end')-scalar('start'),1e-8)))
    edge=b._edge_piece(g,pb.outputs['Geometry'],c._read(g,corners,'st_cc_sb',corner),old('parameter',end),
                       old('offset',end)+.5*old('width',end),h1,cell,2,owner,polyline=interpolation)
    pieces.append(b._empty(g,edge,is_last))
    needed=g.math('MAXIMUM',2.,2.*g.math('CEIL',old('width',end)/(2.*cell)));count=g.math('MINIMUM',needed,b.MAX_PIECE_POINTS)
    axis=c._right(c._vec(g,old('tangent',end,'FLOAT_VECTOR')))
    if interpolation:
        from .curved_exact_profile_nodes import mouth_axis
        axis=mouth_axis(g,originals,end)
    u=1.-i/count;xy=c._add(c._vec(g,old('position',end,'FLOAT_VECTOR')),c._scale(axis,(u-.5)*old('width',end)))
    mouth=b._piece(g,c._line(g,count),g.xyz(*xy),kind=3,owner=g.math('MODULO',owner+1.,nl),parameter=u,
        height=b._profile(g,u,old('half',end,'INT'),old('rise',end))+old('datum',end),
        budget=g.math('LESS_THAN',needed,b.MAX_PIECE_POINTS+.5))
    pieces.append(b._empty(g,mouth,is_last))
    emitted=c._store(g,b._join(g,*pieces),'st_cj_chain_step',at,'INT')
    g.bind(b._join(g,ri.outputs['Geometry'],emitted),ro.inputs['Geometry'])
    return ro.outputs['Geometry']


def _finish(g,inp,ordered,mouths,corners,approaches,steps,basic,joins,*,guard_internal_footprints=False,interpolation=False):
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);count=c._count(g,ordered)
    budget=g.math('GREATER_THAN',count,3.5)*g.math('LESS_THAN',count,b.MAX_BOUNDARY_POINTS+.5)
    budget=budget*c._stat(g,ordered,c.named(g,'st_cj_budget','BOOLEAN'))
    circle=g.node('GeometryNodeMeshCircle');circle.fill_type='NONE'
    g.bind(c.choose(g,budget,count,4,'INT'),circle.inputs['Vertices'])
    wire=g.setpos(circle.outputs['Mesh'],c._sample(g,ordered,g.position(),i,'FLOAT_VECTOR'))
    for key,kind in (('piece','INT'),('owner','INT'),('parameter','FLOAT'),('height','FLOAT'),('chain_step','INT')):
        wire=c._store(g,wire,'st_cj_'+key,c._read(g,ordered,'st_cj_'+key,i,kind),kind)
    from .path_surface_nodes import _Nodes
    from . import blocked_boundary_nodes
    helper=_Nodes(g.g);idx=helper.node('GeometryNodeInputIndex','Boundary ordinal').outputs[0]
    position=helper.node('GeometryNodeInputPosition','Original curb chain').outputs[0]
    clear=blocked_boundary_nodes.check(helper,wire.s,count.s,idx,position,1e-6)
    nxt=c._vec(g,c._sample(g,wire,g.position(),g.math('MODULO',i+1.,g.math('MAXIMUM',count,1.)),'FLOAT_VECTOR'))
    area=c._stat(g,wire,c._cross(c._vec(g,g.position()),nxt),'Sum')*.5
    wire_valid=budget*c.V(g,clear)*g.math('GREATER_THAN',area,1e-5)
    datum=c._read(g,mouths,'st_cj_datum',0);x,y,_=g.separate(g.position())
    raised=g.setpos(wire,g.xyz(x,y,datum+(c.named(g,'st_cj_height')-datum)*c.V(g,inp.outputs['Height Exaggeration'])))
    diagnostic=c._line(g,1)
    for key,value,kind in (('count',count,'INT'),('area',area,'FLOAT'),('budget',budget,'BOOLEAN'),('contact_clear',clear,'BOOLEAN')):
        diagnostic=c._store(g,diagnostic,'st_cj_'+key,value,kind)
    out=g.node('NodeGroupOutput');valid=joins*wire_valid;checked=False
    if guard_internal_footprints:
        from . import curved_chain_footprint_nodes
        call=g.node('GeometryNodeGroup','Complete original curved carriageway footprints')
        call.node_tree=curved_chain_footprint_nodes.build(interpolation=interpolation)
        for key in ('Sources','Mapping','Cell Size'):g.bind(inp.outputs[key],call.inputs[key])
        for key,value in (('Approaches',approaches),('Steps',steps),('Boundary',wire),('Input Valid',valid)):
            g.bind(value,call.inputs[key])
        checked=valid;valid=valid*c.V(g,call.outputs['Valid'])
        g.bind(call.outputs['Ribbons'],out.inputs['Footprint Ribbons']);g.bind(call.outputs['Status'],out.inputs['Footprint Status'])
    for key,value in (('Boundary',b._empty(g,raised,valid)),('Inspection Boundary',raised),('Mouths',mouths),
                      ('Corners',corners),('Approaches',approaches),('Evaluated Steps',steps),('Diagnostics',diagnostic),
                      ('Valid',valid),('Inputs Valid',basic),('Joins Valid',joins),('Wire Valid',wire_valid),('Footprints Checked',checked)):
        g.bind(value,out.inputs[key])
    return g.g
